import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Weekly } from '../types'

const weekly = atom({ plugin: 'weekly-usage', key: 'weekly' } as const, null)
const warned = atom({ plugin: 'weekly-usage', key: 'warned' } as const, false)

const WARN_AT = 80
const HOUR = 60 * 60 * 1000
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

// { day: "Thu Oct 16", clock: "9:00 AM" } in the machine's local time.
const resetParts = (iso: string): { day: string; clock: string } | null => {
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return null
  const h = d.getHours()
  const m = String(d.getMinutes()).padStart(2, '0')
  return {
    day: `${DAYS[d.getDay()]} ${MONTHS[d.getMonth()]} ${d.getDate()}`,
    clock: `${h % 12 === 0 ? 12 : h % 12}:${m} ${h < 12 ? 'AM' : 'PM'}`,
  }
}

// "Thu Oct 16, 9:00 AM" in the machine's local time.
export const formatReset = (iso: string): string => {
  const p = resetParts(iso)
  return p ? `${p.day}, ${p.clock}` : iso
}

export const describe = (w: Weekly): string =>
  `Weekly allowance: ${w.percentUsed}% used` +
  (w.resetsAt ? ` · resets ${formatReset(w.resetsAt)}` : '')

type Segment = { text: string; bold?: boolean }

// The line in parts, the ones to stand out marked bold: the percentage at
// WARN_AT and above; the reset's date and time within 48 hours of it, only
// its time within 24 hours.
export const segments = (w: Weekly, now: number): Segment[] => {
  const out: Segment[] = [
    { text: 'Weekly allowance: ' },
    { text: `${w.percentUsed}%`, bold: w.percentUsed >= WARN_AT },
    { text: ' used' },
  ]
  if (!w.resetsAt) return out

  const p = resetParts(w.resetsAt)
  if (!p) return [...out, { text: ` · resets ${w.resetsAt}` }]

  const left = new Date(w.resetsAt).getTime() - now
  out.push({ text: ' · resets ' })
  if (left <= 24 * HOUR) {
    out.push({ text: `${p.day}, ` }, { text: p.clock, bold: true })
  } else if (left <= 48 * HOUR) {
    out.push({ text: `${p.day}, ${p.clock}`, bold: true })
  } else {
    out.push({ text: `${p.day}, ${p.clock}` })
  }
  return out
}

export const register: Register = on => {
  on('session.measure', async ($, e, next) => {
    const window = e.rateLimits.find(r => r.kind === 'seven_day')
    if (window) {
      const w: Weekly = { percentUsed: window.percentUsed, resetsAt: window.resetsAt ?? null }
      await update($, weekly, () => w)

      // One toast per crossing: re-arms when usage drops back (a new week).
      if (w.percentUsed < WARN_AT) {
        await update($, warned, () => false)
      } else if (!(await read($, warned))) {
        await update($, warned, () => true)
        $.ui.toast(`${describe(w)}`)
      }
    }

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const w = await read($, weekly)
    if (e.props.hasSurvey || w === null) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)
    const now = await $.clock.now()

    // Dim by default; a bold part is drawn in the normal font color.
    return (
      <Box>
        <Text key="weekly">
          {segments(w, now).map(s => (s.bold ? <Text bold>{s.text}</Text> : <Text dimColor>{s.text}</Text>))}
        </Text>
      </Box>
    )
  })
}

